#!/usr/bin/env python3
# Write src/audio/birdcalls.ts from scripts/birds/templates.json (made by build.py): numbers only.
import json, os
here = os.path.dirname(__file__)
T = json.load(open(os.path.join(here, 'templates.json')))
def arr(v, nd=0): return '[' + ', '.join((str(round(x, nd)) if nd else str(int(round(x)))) if isinstance(x, (int, float)) else str(x) for x in v) + ']'
lines = ['// GENERATED by scripts/birds/gen_ts.py from scripts/birds/templates.json (scripts/birds/build.py): the call templates measured on real recordings, numbers only (design/birds.md).',
         '// Do not edit by hand. Each is the median over several calls in several recordings; no recording, nor any part of one, is in the source.', '',
         "import type { CallTemplate } from './birdsynth';", '', 'export interface MeasuredCall extends CallTemplate {',
         '  /** The gap between one call and the next in a bout (10th, 50th, 90th percentile, seconds), and the number in a bout. */', '  gap: [number, number, number] | null;', '  bout: [number, number, number] | null;',
         '  /** Amplitude modulation of a long call: rate in Hz and depth 0..1 (a whirr). */', '  am?: [number, number];', '}', '', 'export const CALLS = {']
for k, v in T.items():
    lines.append(f"  {k}: {{ dur: {v['dur']:.3f}, durRange: [{v['durRange'][0]:.3f}, {v['durRange'][1]:.3f}], f0: {arr(v['f0'])}, f0Spread: {v['f0Spread']:.3f}, env: {arr(v['env'], 1)},")
    lines.append(f"    bands: {arr(v['bands'])},")
    lines.append(f"    H: {arr(v['H'], 0)},")
    lines.append(f"    N: {arr(v['N'], 0)},")
    lines.append(f"    gap: {arr(v['gap'], 2) if v.get('gap') else 'null'}, bout: {arr(v['bout']) if v.get('bout') else 'null'}" + (f", am: {arr(v['am'], 2)}" if v.get('am') else '') + ' },')
lines += ['} satisfies Record<string, MeasuredCall>;', '', 'export type CallName = keyof typeof CALLS;', '']
open(os.path.join(here, '../../src/audio/birdcalls.ts'), 'w').write('\n'.join(lines))
print('wrote src/audio/birdcalls.ts', sum(len(l) for l in lines), 'bytes')
